namespace {
size_t checks=0;void check(bool value,const char *text){if(!value)throw std::runtime_error(text);std::cout<<"PASS "<<text<<std::endl;++checks;}
void ready(Document &doc){check(doc.wait_asset(std::chrono::seconds(120))&&doc.wait_mesh(std::chrono::seconds(120))&&doc.frame().state->error.empty(),"Actual Normal authoring worker retires cleanly");}
template<class F>std::string error(F f){try{f();}catch(const std::exception&e){return e.what();}return {};}
void saved(Document &doc,const std::filesystem::path &path){auto f=doc.save_async(path);check(doc.wait_native_stroke(std::chrono::seconds(120))&&doc.wait_asset(std::chrono::seconds(120)),"Queued Save observes native/asset publication phases");check(f.wait_for(std::chrono::seconds(120))==std::future_status::ready,"Ordered Normal Save future becomes ready");f.get();ready(doc);}
}
