 Vrm1ExpressionWeights weights;weights.preset["happy"]=.35f;const auto expected=bake_vrm1_expression_pose(baseline,id,weights);check(expected.encode()!=exact&&baseline.encode()==exact,"Actual static Normal kernel changes its detached result only");
